    return <Object?>[id, title, text, accept, reject, seconds];
  }

  Object encode() {
    return _toList();
  }

  static CarAlert decode(Object result) {
    result as List<Object?>;
    return CarAlert(
      id: result[0]! as String,
      title: result[1]! as String,
      text: result[2]! as String,
      accept: result[3]! as String,
      reject: result[4]! as String,
      seconds: result[5]! as int,
    );
  }

  @override
  // ignore: avoid_equals_and_hash_code_on_mutable_classes
  bool operator ==(Object other) {
    if (other is! CarAlert || other.runtimeType != runtimeType) {
      return false;
    }
    if (identical(this, other)) {
      return true;
    }
    return _deepEquals(id, other.id) &&
        _deepEquals(title, other.title) &&
        _deepEquals(text, other.text) &&
        _deepEquals(accept, other.accept) &&
        _deepEquals(reject, other.reject) &&
        _deepEquals(seconds, other.seconds);
  }

  @override
  // ignore: avoid_equals_and_hash_code_on_mutable_classes
  int get hashCode => _deepHash(<Object?>[runtimeType, ..._toList()]);

  @override
  String toString() {
    return 'CarAlert(id: $id, title: $title, text: $text, accept: $accept, reject: $reject, seconds: $seconds)';
  }
}

class _PigeonCodec extends StandardMessageCodec {
  const _PigeonCodec();
  @override
  void writeValue(WriteBuffer buffer, Object? value) {
    if (value is int) {
      buffer.putUint8(4);
      buffer.putInt64(value);
    } else if (value is CarManeuverType) {
      buffer.putUint8(129);
      writeValue(buffer, value.index);
    } else if (value is CarPlace) {
      buffer.putUint8(130);
      writeValue(buffer, value.encode());
    } else if (value is CarRouteSummary) {
      buffer.putUint8(131);
      writeValue(buffer, value.encode());
    } else if (value is CarRoadSign) {
      buffer.putUint8(132);
      writeValue(buffer, value.encode());
    } else if (value is CarLane) {
      buffer.putUint8(133);
      writeValue(buffer, value.encode());
    } else if (value is CarManeuver) {
      buffer.putUint8(134);
      writeValue(buffer, value.encode());
    } else if (value is CarTrip) {
      buffer.putUint8(135);
      writeValue(buffer, value.encode());
    } else if (value is CarSpeed) {
      buffer.putUint8(136);
      writeValue(buffer, value.encode());
    } else if (value is CarPosition) {
      buffer.putUint8(137);
      writeValue(buffer, value.encode());
    } else if (value is CarCamera) {
      buffer.putUint8(138);
      writeValue(buffer, value.encode());
    } else if (value is CarBounds) {
      buffer.putUint8(139);
      writeValue(buffer, value.encode());
    } else if (value is CarSurface) {
      buffer.putUint8(140);
      writeValue(buffer, value.encode());
    } else if (value is CarAlert) {
      buffer.putUint8(141);
      writeValue(buffer, value.encode());
    } else {
      super.writeValue(buffer, value);
    }
  }

  @override
  Object? readValueOfType(int type, ReadBuffer buffer) {
    switch (type) {
      case 129:
        final value = readValue(buffer) as int?;
        return value == null ? null : CarManeuverType.values[value];
      case 130:
        return CarPlace.decode(readValue(buffer)!);
      case 131:
        return CarRouteSummary.decode(readValue(buffer)!);
      case 132:
        return CarRoadSign.decode(readValue(buffer)!);
      case 133:
        return CarLane.decode(readValue(buffer)!);
      case 134:
        return CarManeuver.decode(readValue(buffer)!);
      case 135:
        return CarTrip.decode(readValue(buffer)!);
      case 136:
        return CarSpeed.decode(readValue(buffer)!);
      case 137:
        return CarPosition.decode(readValue(buffer)!);
      case 138:
        return CarCamera.decode(readValue(buffer)!);
      case 139:
        return CarBounds.decode(readValue(buffer)!);
      case 140:
        return CarSurface.decode(readValue(buffer)!);
      case 141:
        return CarAlert.decode(readValue(buffer)!);
      default:
        return super.readValueOfType(type, buffer);
    }
  }
}

