/// The car to Dart: what the driver does.
abstract class CarFlutterApi {
  static const MessageCodec<Object?> pigeonChannelCodec = _PigeonCodec();

  void connected(CarSurface surface);

  void disconnected();

  /// The screen size or dark mode changed.
  void surfaceChanged(CarSurface surface);

  void placeChosen(String id);

  Future<List<CarPlace>> search(String text);

  void routeChosen(int index);

  void startTrip();

  void stopTrip();

  void toggleMute();

  /// The driver panned or zoomed: following stops.
  void userMovedMap();

  void recenter();

  void alertAnswered(String id, bool accepted);

  /// Android's test drive (the review requires it): a fake GPS drives the
  /// route.
  void autoDriveEnabled();

  /// A `geo:` or navigation intent in the car: a point with a name, or a
  /// search text.
  void navigateTo(double? lat, double? lon, String? label, String? query);

  void backToHome();

  static void setUp(
    CarFlutterApi? api, {
    BinaryMessenger? binaryMessenger,
    String messageChannelSuffix = '',
  }) {
    messageChannelSuffix = messageChannelSuffix.isNotEmpty
        ? '.$messageChannelSuffix'
        : '';
    {
      final pigeonVar_channel = BasicMessageChannel<Object?>(
        'dev.flutter.pigeon.homemaps.CarFlutterApi.connected$messageChannelSuffix',
        pigeonChannelCodec,
        binaryMessenger: binaryMessenger,
      );
      if (api == null) {
        pigeonVar_channel.setMessageHandler(null);
      } else {
        pigeonVar_channel.setMessageHandler((Object? message) async {
          final List<Object?> args = message! as List<Object?>;
          final CarSurface arg_surface = args[0]! as CarSurface;
          try {
            api.connected(arg_surface);
            return wrapResponse(empty: true);
          } on PlatformException catch (e) {
            return wrapResponse(error: e);
          } catch (e) {
            return wrapResponse(
              error: PlatformException(code: 'error', message: e.toString()),
            );
          }
        });
      }
    }
    {
      final pigeonVar_channel = BasicMessageChannel<Object?>(
        'dev.flutter.pigeon.homemaps.CarFlutterApi.disconnected$messageChannelSuffix',
        pigeonChannelCodec,
        binaryMessenger: binaryMessenger,
      );
      if (api == null) {
        pigeonVar_channel.setMessageHandler(null);
      } else {
        pigeonVar_channel.setMessageHandler((Object? message) async {
          try {
            api.disconnected();
            return wrapResponse(empty: true);
          } on PlatformException catch (e) {
            return wrapResponse(error: e);
          } catch (e) {
            return wrapResponse(
              error: PlatformException(code: 'error', message: e.toString()),
            );
          }
        });
      }
    }
    {
      final pigeonVar_channel = BasicMessageChannel<Object?>(
        'dev.flutter.pigeon.homemaps.CarFlutterApi.surfaceChanged$messageChannelSuffix',
        pigeonChannelCodec,
